package com.tapeverify.copilot.service;
import com.tapeverify.copilot.dto.AiSuggestionDto; import com.tapeverify.copilot.entity.*; import com.tapeverify.copilot.exception.LoanNotFoundException; import com.tapeverify.copilot.repository.*; import java.math.BigDecimal; import java.time.LocalDateTime; import org.springframework.ai.chat.client.ChatClient; import org.springframework.beans.factory.ObjectProvider; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service;
@Service public class AiCopilotServiceImpl implements AiCopilotService { private final LoanRepository loans; private final ValidationExceptionRepository exceptions; private final ObjectProvider<ChatClient.Builder> chatClientBuilder; private final AuditService audit; public AiCopilotServiceImpl(LoanRepository loans,ValidationExceptionRepository exceptions,ObjectProvider<ChatClient.Builder> chatClientBuilder,AuditService audit){this.loans=loans;this.exceptions=exceptions;this.chatClientBuilder=chatClientBuilder;this.audit=audit;} public AiSuggestionDto explain(Long loanId,Long exceptionId){var loan=loans.findById(loanId).orElseThrow(()->new LoanNotFoundException(loanId));ValidationException error=exceptionId==null?exceptions.findByLoanIdAndResolvedFalse(loanId).stream().findFirst().orElseThrow(()->new IllegalArgumentException("This loan has no open exceptions")):exceptions.findById(exceptionId).filter(e->e.getLoan().getId().equals(loanId)&&!e.isResolved()).orElseThrow(()->new IllegalArgumentException("Open exception not found for this loan"));String suggested=suggestion(error.getFieldName()),explanation=error.getErrorMessage(),reasoning="Deterministic validation guidance based on the configured rule.";boolean fallback=true;String prompt="Explain this validation exception and suggest a safe, reviewer-controlled remediation. Field: "+error.getFieldName()+"; message: "+error.getErrorMessage()+"; raw input: "+error.getRawValue();error.setAiRequestedAt(LocalDateTime.now());error.setAiProvider("rule-based");error.setAiModel("deterministic-v1");error.setAiPrompt(prompt);try{ChatClient.Builder builder=chatClientBuilder.getIfAvailable();if(builder!=null){String response=builder.build().prompt().user(prompt).call().content();if(response!=null&&!response.isBlank()){explanation=response;reasoning="AI-generated explanation; reviewer approval is still required.";fallback=false;error.setAiProvider("openai");error.setAiModel("configured-chat-model");}}}catch(Exception e){error.setAiFailure(e.getClass().getSimpleName()+": provider unavailable");explanation="AI assistance is temporarily unavailable. "+error.getErrorMessage();reasoning="Fallback guidance returned; provider failure recorded for diagnostics.";}error.setAiExplanation(explanation);error.setAiSuggestedValue(suggested);error.setAiConfidence(fallback?new BigDecimal("0.800"):new BigDecimal("0.650"));error.setAiReasoningSummary(reasoning);exceptions.save(error);audit.record(loan,AuditAction.AI_RECOMMENDATION_GENERATED,SecurityContextHolder.getContext().getAuthentication().getName(),null,null);return AiSuggestionDto.builder().exceptionId(error.getId()).fieldName(error.getFieldName()).explanation(explanation).suggestedValue(suggested).confidence(error.getAiConfidence()).reasoningSummary(reasoning).provider(error.getAiProvider()).model(error.getAiModel()).requestedAt(error.getAiRequestedAt()).prompt(error.getAiPrompt()).fallback(fallback).build();} private String suggestion(String field){return switch(field){case "interestRate"->"Use a rate between 0.01 and 30.00";case "principalAmount"->"Enter a positive principal amount";case "currentBalance"->"Set a non-negative balance not greater than original principal";case "maturityDate"->"Set a date later than the origination date";case "documentStatus"->"Use AVAILABLE, PENDING, MISSING, or NOT_AVAILABLE";default->"Provide a valid value for this required field";};} }
